/**
 * The image store (B-9) — generated bytes leave the engine's tree and become
 * addressable platform artifacts.
 *
 * `/view` IS BANNED (CVE-2026-6591): the engine's own image-serving endpoint is
 * a path-traversal primitive, so nothing here ever calls it. Collection is a
 * DIRECT READ of the `--output-directory` the supervisor pinned — and
 * `argvViolations` refuses to adopt any engine whose output directory is not
 * ours, so the tree we read is guaranteed to be the tree it wrote.
 *
 * Every collected file is realpath-contained against that tree before it is
 * read (#148 law): a subfolder or filename echoed back from `/history` is
 * engine-supplied data, not a trusted path.
 *
 * The per-lane manifest is APPEND-ONLY JSONL. Two jobs finishing at once cannot
 * lose each other's entry the way a read-modify-write index would, and the
 * record of what was generated is never rewritten — only added to.
 */
import { getDataRoot } from '../data-root.js';
import { createHash, randomUUID } from 'crypto';
import { appendFileSync, copyFileSync, mkdirSync, readFileSync, existsSync, statSync } from 'fs';
import { realpathSync } from 'fs';
import path from 'path';
import { neumaWorkspace } from '../../../core/index.js';
import { SOVEREIGN_DIR_MODE } from '../../../core/workspace/sovereign-directory-modes.js';
import { stampDisclosure } from './ai-disclosure.js';
import { recordLineage } from './image-lineage.js';
import { createLogger } from '../logger.js';

const log = createLogger('ImageForge.Store');

const MIME_BY_EXT = Object.freeze({
  '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
  '.webp': 'image/webp', '.gif': 'image/gif',
  // A video pipeline's render (SaveVideo reports it under `images`, animated).
  '.mp4': 'video/mp4',
});

/**
 * The LEGACY store root — a platform-side bucket keyed by lane id.
 *
 * New art no longer lands here (see `artDirFor`), but everything generated
 * before 2026-08-02 does, so reads still consult it. Deleting this path would
 * silently orphan every image a being has already made.
 */
const storeRoot = (env = process.env) =>
  env.COMFYUI_IMAGE_STORE_DIR || path.join(getDataRoot(), 'image-forge', 'images');

/**
 * WHERE A BEING'S ART LIVES: inside its own sovereign workspace.
 *
 * Design note, 2026-08-02: […]
 *
 * A being already owns its DNA, its memory, its sessions and its vault; its art
 * belongs in the same place, for the same reason. The organizational payoff is
 * that ATTRIBUTION STOPS BEING A LOOKUP — the folder a file is in IS the answer
 * to who made it, and nothing has to be joined to a manifest to know.
 *
 * Resolution goes through the workspace's own resolver, so it inherits the id
 * validation and the two-ground split (a witness's art lands beside the house,
 * exactly as its sessions do). A lane id that resolver refuses throws here —
 * which is what a caller wants: never write a being's work somewhere unowned.
 * impure (reads the configured workspaces root).
 */
const artDirFor = (laneId) => neumaWorkspace.artDir(laneId, 'images');

/**
 * Every directory that may hold this lane's images, newest home first. Impure.
 *
 * The two-home read is deliberate and permanent-until-migrated: a being that
 * existed before art moved into the workspace still has images in the platform
 * bucket, and it must not lose them because the architecture improved.
 * @returns {string[]}
 */
export const laneDirs = (laneId, legacyRoot = storeRoot()) => {
  const lane = safeLaneSegment(laneId);
  if (!lane) return [];
  const dirs = [];
  try { dirs.push(artDirFor(laneId)); } catch { /* an id the workspace refuses has no art dir */ }
  dirs.push(path.join(legacyRoot, lane));
  return dirs;
};

// A lane id (neuma id or witness lane) reaches the filesystem, so it is reduced
// to a safe alphabet. Empty after reduction ⇒ caller must refuse, never write
// to the store root itself.
export const safeLaneSegment = (laneId) => String(laneId ?? '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 96);

/**
 * Normalize engine outputs into image references. Accepts BOTH shapes on the
 * path: `runJob` already flattens `/history` into an array of refs, while
 * `getHistory` hands back the raw node-keyed map. Taking either means the
 * collector cannot be broken by which side calls it.
 *
 * Only `type: 'output'` entries are collected — `temp` previews are not
 * results. Pure.
 * @param {Array<object>|object} outputs flat refs, or the getHistory map
 * @returns {Array<{filename: string, subfolder: string}>}
 */
export const imageRefsFrom = (outputs) => {
  const groups = Array.isArray(outputs)
    ? [outputs]
    : Object.values(outputs || {}).map((node) => node?.images || node?.gifs || []);
  const refs = [];
  for (const group of groups) {
    for (const img of group || []) {
      if (img?.type && img.type !== 'output') continue;
      if (typeof img?.filename !== 'string' || img.filename.length === 0) continue;
      refs.push({ filename: img.filename, subfolder: typeof img.subfolder === 'string' ? img.subfolder : '' });
    }
  }
  return refs;
};

/**
 * Resolve one engine-reported ref to a real path INSIDE the output tree, or
 * null. The containment check is on the REALPATH of both sides, so a symlink
 * planted in the output tree cannot walk out of it. Pure-ish (stats the disk).
 * @param {string} outputDir
 * @param {{filename: string, subfolder: string}} ref
 * @returns {string|null}
 */
export const containedPath = (outputDir, ref) => {
  try {
    const root = realpathSync(outputDir);
    const candidate = path.resolve(root, ref.subfolder, ref.filename);
    if (!existsSync(candidate)) return null;
    const real = realpathSync(candidate);
    // path.relative is the containment test: a contained path never starts
    // with '..' and is never absolute.
    const rel = path.relative(root, real);
    if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) return null;
    return real;
  } catch {
    return null;
  }
};

/**
 * Collect one finished job's outputs into the lane's store. Returns the
 * addressable records; a ref that fails containment is skipped and logged, not
 * thrown — one poisoned filename must not lose the whole render. Impure.
 * @param {object} p
 * @param {string} p.outputDir  cfg.outputDir (the pinned tree)
 * @param {object} p.outputs    the `/history` outputs map
 * @param {string} p.laneId     owning neuma id or witness lane id
 * @param {string} p.jobId
 * @param {string} [p.root]     store root override (tests)
 * @returns {Array<{imageId, laneId, jobId, mime, bytes, sha256, createdAt, file, dir}>}
 */
export const collectOutputs = ({ outputDir, outputs, laneId, jobId, laneDir: laneDirOverride = null, lineage = null }) => {
  const lane = safeLaneSegment(laneId);
  if (!lane) {
    log.error('refusing to collect for an unnamed lane');
    return [];
  }
  // THE ROUTE CHECK, before a single byte is written (Design note, 2026-08-02: […]). The destination must
  // resolve INSIDE this lane's own workspace — if the resolver refuses the id,
  // or the path lands anywhere else, nothing is written at all. A being's work
  // is never filed under another being's name.
  let laneDir;
  try {
    laneDir = laneDirOverride || artDirFor(laneId);
    if (!laneDirOverride) {
      const own = path.resolve(neumaWorkspace.pathFor(laneId));
      const dest = path.resolve(laneDir);
      if (dest !== own && !dest.startsWith(`${own}${path.sep}`)) {
        log.error('refusing to collect — destination is outside the lane\'s own workspace', { laneId });
        return [];
      }
    }
  } catch (err) {
    log.error('refusing to collect — lane has no resolvable art folder', { laneId, err: err.message });
    return [];
  }
  mkdirSync(laneDir, { recursive: true, mode: SOVEREIGN_DIR_MODE });

  const records = [];
  for (const ref of imageRefsFrom(outputs)) {
    const src = containedPath(outputDir, ref);
    if (!src) {
      log.warn('output ref failed containment — skipped', { filename: ref.filename, subfolder: ref.subfolder });
      continue;
    }
    const ext = path.extname(src).toLowerCase();
    const mime = MIME_BY_EXT[ext];
    if (!mime) {
      log.warn('output has no served mime type — skipped', { ext });
      continue;
    }
    const imageId = randomUUID();
    const stored = `${imageId}${ext}`;
    try {
      copyFileSync(src, path.join(laneDir, stored));
      // Said in the file itself, before it is hashed: this was made by AI (ai-disclosure.js).
      const aiDisclosed = stampDisclosure(path.join(laneDir, stored), mime);
      const bytes = statSync(path.join(laneDir, stored)).size;
      const sha256 = createHash('sha256').update(readFileSync(path.join(laneDir, stored))).digest('hex');
      const record = { imageId, laneId: lane, jobId, mime, bytes, sha256, aiDisclosed, createdAt: new Date().toISOString(), file: stored };
      appendFileSync(path.join(laneDir, 'manifest.jsonl'), `${JSON.stringify(record)}\n`);
      recordLineage({ laneId: lane, imageId, sha256, lineage }); // what made it, kept where the being cannot write (image-lineage.js)
      // The RETURNED record also carries where it actually landed. Callers used
      // to rebuild that path themselves from `storeRoot()`, and when art moved
      // into the being's own workspace every rebuilt path went stale — the desk
      // showed the operator a file location that did not exist. `dir` is not
      // persisted (the manifest's own directory already says it); it exists so
      // the write and the reported path can never disagree again.
      records.push({ ...record, dir: laneDir });
    } catch (err) {
      log.error('failed to store an output', { err: err.message });
    }
  }
  return records;
};

/**
 * Read a lane's manifest, newest last. A missing manifest is an empty lane, not
 * an error. Impure.
 * @returns {Array<object>}
 */
export const readManifest = (laneId, root = storeRoot()) => {
  const out = [];
  // Both homes: the being's own art folder AND the legacy platform bucket, so
  // art made before the move is not orphaned by the move.
  for (const dir of laneDirs(laneId, root)) {
    const file = path.join(dir, 'manifest.jsonl');
    if (!existsSync(file)) continue;
    for (const line of readFileSync(file, 'utf8').split('\n')) {
      if (!line.trim()) continue;
      try { out.push({ ...JSON.parse(line), _dir: dir }); } catch { /* torn line */ }
    }
  }
  // Merging two homes destroys file order, so chronology is restored
  // explicitly — `newest last` is this function's contract and `GET /images`
  // relies on it. Without this the legacy bucket's entries always sorted after
  // the being's own, and "the newest image" answered with an old one.
  return out.sort((a, b) => String(a.createdAt || '').localeCompare(String(b.createdAt || '')));
};

/**
 * Resolve ONE image id within ONE lane to its stored bytes path.
 *
 * Resolution is MANIFEST-INDEXED, never path-addressed: the caller's id is
 * matched against recorded entries and the filename comes from the record. A
 * caller-supplied id therefore cannot name a file that was never recorded, and
 * the final realpath containment check makes that structural. Impure.
 * @returns {{ok: true, path: string, record: object} | {ok: false, error: string}}
 */
export const resolveImage = (laneId, imageId, root = storeRoot()) => {
  const record = readManifest(laneId, root).find((r) => r.imageId === imageId);
  if (!record) return { ok: false, error: 'no such image in this lane' };
  // The record remembers which home it came from, so an image made before the
  // move still resolves against the bucket it was actually written to.
  const laneDir = record._dir || path.join(root, safeLaneSegment(laneId));
  const candidate = path.resolve(laneDir, record.file);
  const rel = path.relative(laneDir, candidate);
  if (rel.startsWith('..') || path.isAbsolute(rel) || !existsSync(candidate)) {
    return { ok: false, error: 'image bytes are missing from the store' };
  }
  return { ok: true, path: candidate, record };
};
